// Preview templates for Sveltia CMS: show families, creative direction levels and galleries with the website's
// own styles (preview.css is a copy of src/styles/global.css, generated by scripts/cms-config.mjs).
// Sveltia bundles React and exposes `h` (createElement); no build step needed.
(() => {
  const CMS = window.CMS;
  if (!CMS) return;
  const h = window.h || window.createElement || (CMS.React && CMS.React.createElement);

  CMS.registerPreviewStyle('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@400;500;600;700&family=Inter:wght@300;400;500;600&display=swap');
  CMS.registerPreviewStyle('preview.css');
  CMS.registerPreviewStyle('body { padding: 2rem 0; } .reveal { opacity: 1 !important; transform: none !important; } .pack-body > summary { display: none; }', { raw: true });

  const js = (v) => (v && typeof v.toJS === 'function' ? v.toJS() : v);
  // Shared fields (prices, images, order…) live in the Spanish block; other locales may hold null for them.
  const entryData = (entry) => {
    const data = js(entry.get('data')) || {};
    const es = js(entry.getIn(['i18n', 'es', 'data'])) || data;
    return mergeShared(es, data);
  };
  const SHARED = new Set(['order', 'visible', 'featured', 'area', 'image', 'cover_image', 'cover_position', 'position', 'images', 'name', 'amount', 'kind', 'vat_mode', 'unit', 'plus']);
  const isEmpty = (v) => v === undefined || v === null || v === '';
  // Translation over Spanish: shared keys always from Spanish, the rest from the previewed locale when set.
  function mergeShared(base, over) {
    if (Array.isArray(base)) return base.map((b, i) => mergeShared(b, Array.isArray(over) ? over[i] : undefined));
    if (base && typeof base === 'object') {
      const out = {};
      for (const k of new Set([...Object.keys(base), ...Object.keys(over || {})])) {
        const o = over ? over[k] : undefined;
        out[k] = SHARED.has(k) ? (isEmpty(base[k]) ? o : base[k]) : mergeShared(base[k], o);
      }
      return out;
    }
    return isEmpty(over) ? base : over;
  }

  // Same rules as src/lib/price.ts (Spanish format in the preview).
  const money = (n) => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.') + ' €';
  const UNIT = { month: '/mes', unit: '/unidad', piece: '/pieza' };
  function priceText(p, vat = true) {
    if (!p || !p.kind) return '';
    if (p.kind === 'quote' || p.amount == null || p.amount === '') return p.note ? `Presupuesto ${p.note}` : 'Presupuesto personalizado';
    let a = money(p.amount);
    if (p.unit && UNIT[p.unit]) a = a.replace(' €', ` €${UNIT[p.unit]}`);
    if (p.plus) a = '+' + a;
    const parts = [p.kind === 'from' ? `Desde ${a}` : a];
    if (p.note) parts.push(p.note);
    if (vat && p.vat_mode === 'included') parts.push('IVA incluido');
    if (vat && p.vat_mode === 'excluded') parts.push('+ IVA');
    return parts.join(' ');
  }
  // Same light markup as src/lib/text.ts.
  const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const md = (s) => ({ __html: s ? esc(s.trim()).replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>').replace(/(^|[^*])\*([^*\n]+?)\*(?!\*)/g, '$1<em>$2</em>').replace(/\r?\n/g, '<br>') : '' });
  // The admin lives at <base>/admin/, so the site's base path (e.g. /studio-belvi-prototipo) is what comes before it.
  const BASE = location.pathname.replace(/\/admin(\/.*)?$/, '');
  const assetUrl = (getAsset, src) => {
    if (!src) return '';
    try { const a = getAsset && getAsset(src); if (a && typeof a.then !== 'function' && String(a) !== '[object Object]') return String(a); } catch (e) {}
    return src.startsWith('/') ? BASE + src : src;
  };
  const AREA = { memorabilia: 'Memorabilia', scenography: 'Escenografía', immersion: 'Inmersión' };
  const EXTRAS = { additional_piece: 'Piezas adicionales', combo: 'Combinaciones', addon: 'Ampliaciones', support: 'Acompañamiento' };
  const list = (items) => h('ul', { className: 'check-list' }, (items || []).filter(Boolean).map((t, i) => h('li', { key: i }, t)));

  // ---------- Family (Packs) ----------
  function FamilyPreview({ entry, getAsset }) {
    const f = entryData(entry);
    const packs = (f.packs || []).filter((p) => p && p.visible !== false);
    const extras = f.extras || [];
    return h('div', { className: 'container' },
      h('div', { className: 'family-hero' },
        h('div', { className: 'section-header', style: { marginBottom: 0 } },
          h('span', null, AREA[f.area] || ''),
          h('h2', null, f.name || ''),
          h('p', { dangerouslySetInnerHTML: md(f.tagline) }),
          f.intro ? h('p', { style: { marginTop: '1rem' }, dangerouslySetInnerHTML: md(f.intro) }) : null,
          f.price_from ? h('span', { className: 'price' }, priceText(f.price_from)) : null),
        f.cover_image ? h('img', { src: assetUrl(getAsset, f.cover_image), style: { objectPosition: f.cover_position || '50% 50%' } }) : null),
      (f.common_inclusions || []).length ? h('div', { className: 'panel subsection' }, h('h3', null, 'Incluye en todos los niveles'), list(f.common_inclusions)) : null,
      h('div', { className: 'pack-list subsection' }, packs.map((p, i) =>
        h('article', { className: 'pack', key: i },
          h('div', { className: 'pack-head' },
            packs.length > 1 ? h('div', { className: 'pack-number' }, String(i + 1).padStart(2, '0') + '.') : null,
            p.featured ? h('span', { className: 'badge' }, 'Destacado') : null,
            h('h3', null, p.name || ''),
            h('span', { className: 'price' }, priceText(p.price)),
            p.description ? h('p', { dangerouslySetInnerHTML: md(p.description) }) : null),
          h('div', { className: 'pack-body' },
            (p.inclusion_groups || []).map((g, j) => h('div', { key: j }, h('h4', null, (g && g.title) || 'Incluye'), g && g.description ? h('p', null, g.description) : null, list(g && g.items))),
            (p.possibilities || []).length ? h('div', null, h('h4', null, 'Posibilidades'), list(p.possibilities)) : null)))),
      Object.keys(EXTRAS).map((kind) => {
        const items = extras.filter((e) => e && e.kind === kind);
        if (!items.length) return null;
        return h('div', { className: 'panel subsection', key: kind }, h('h3', null, EXTRAS[kind]),
          h('div', { className: 'extras' }, items.map((e, i) => h('div', { className: 'extra', key: i },
            h('span', null, h('span', { className: 'label' }, e.label || ''), e.description ? h('span', { className: 'desc' }, e.description) : null),
            h('span', { className: 'price' }, priceText(e.price, false))))));
      }),
      (f.notes || []).map((n, i) => h('p', { className: 'small-note', key: i }, n)));
  }

  // ---------- Creative direction level ----------
  function LevelPreview({ entry }) {
    const l = entryData(entry);
    return h('div', { className: 'container' },
      h('div', { className: 'info' },
        h('div', { className: 'section-header' },
          h('span', null, l.motto || ''), h('h2', null, l.name || ''),
          h('p', { dangerouslySetInnerHTML: md(l.description) }),
          h('p', { style: { marginTop: '1.5rem' } }, h('strong', null, 'Ideal para: '), l.ideal_for || ''),
          h('p', null, l.price_label ? h('span', { className: 'price-label' }, l.price_label + ' · ') : null, h('span', { className: 'price' }, priceText(l.price)))),
        h('div', { className: 'info-grid' }, h('div', null, h('h3', null, 'Incluye'), list(l.includes)))));
  }

  // ---------- Galleries: cards shown front and caption, with the chosen crop ----------
  function GalleryPreview({ entry, getAsset }) {
    const g = entryData(entry);
    return h('div', { className: 'container' },
      h('div', { className: 'section-header' }, h('h2', { dangerouslySetInnerHTML: md(g.title) }), g.text ? h('p', { dangerouslySetInnerHTML: md(g.text) }) : null),
      h('div', { className: 'family-grid' }, (g.cards || []).map((c, i) => c && h('div', { className: 'family-card', key: i },
        h('img', { src: assetUrl(getAsset, c.image), style: { objectPosition: c.position || '50% 50%' } }),
        h('div', { className: 'body' }, h('p', { className: 'tagline', dangerouslySetInnerHTML: md(c.caption) }))))));
  }

  CMS.registerPreviewTemplate('families', FamilyPreview);
  ['sparks', 'chapters', 'universe'].forEach((n) => CMS.registerPreviewTemplate(n, LevelPreview));
  ['memorabilia', 'scenography', 'immersion', 'portfolio'].forEach((n) => CMS.registerPreviewTemplate(n, GalleryPreview));
})();
